begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(51);

insert into auth.users(id,email) select ('91000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'deliverable-'||n||'@example.test' from generate_series(1,10)n;
insert into profiles(id,email,full_name) select id,email,'User '||right(id::text,2) from auth.users where id::text like '91000000-%';
insert into organizations(id,name,created_by) values('92000000-0000-4000-8000-000000000001','Deliverable Org','91000000-0000-4000-8000-000000000001'),('92000000-0000-4000-8000-000000000002','Other Deliverable Org','91000000-0000-4000-8000-000000000010');
insert into organization_members(organization_id,user_id,role,status) values
('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','Administrator','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000002','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000003','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000004','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000005','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000006','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000007','Member','Active'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000008','Member','Inactive'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000009','Member','Active'),('92000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000010','Administrator','Active');
insert into projects(id,organization_id,name,business_objective,project_manager_id,sponsor_name,lifecycle_phase,status,start_date,target_completion_date,overall_health,scope_health,schedule_health,budget_health,resource_health,risk_health,created_by) values
('93000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','Primary Project','Test','91000000-0000-4000-8000-000000000002','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','91000000-0000-4000-8000-000000000001'),
('93000000-0000-4000-8000-000000000002','92000000-0000-4000-8000-000000000001','Sibling Project','Test','91000000-0000-4000-8000-000000000009','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','91000000-0000-4000-8000-000000000001'),
('93000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000002','Other Project','Test','91000000-0000-4000-8000-000000000010','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','91000000-0000-4000-8000-000000000010');
insert into project_members(id,project_id,user_id,access_level,left_at) values
('94000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000002','Project Manager',null),('94000000-0000-4000-8000-000000000002','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000003','Project Member',null),('94000000-0000-4000-8000-000000000003','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000004','Stakeholder',null),('94000000-0000-4000-8000-000000000004','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000005','Read Only',null),('94000000-0000-4000-8000-000000000005','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000007','Project Member',now()),('94000000-0000-4000-8000-000000000006','93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000008','Project Member',null),('94000000-0000-4000-8000-000000000007','93000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000009','Project Manager',null),('94000000-0000-4000-8000-000000000008','93000000-0000-4000-8000-000000000003','91000000-0000-4000-8000-000000000010','Project Manager',null);
insert into milestones(id,project_id,title,target_date,created_by) values('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','Primary milestone','2026-09-01','91000000-0000-4000-8000-000000000001'),('95000000-0000-4000-8000-000000000002','93000000-0000-4000-8000-000000000002','Sibling milestone','2026-09-01','91000000-0000-4000-8000-000000000001'),('95000000-0000-4000-8000-000000000003','93000000-0000-4000-8000-000000000003','Other milestone','2026-09-01','91000000-0000-4000-8000-000000000010');

select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$insert into deliverables(id,project_id,milestone_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('96000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000001','Admin output','Signed evidence','94000000-0000-4000-8000-000000000001','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'Administrator creates with assigned manager owner');
select is((select count(*) from deliverables),1::bigint,'Administrator reads');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);set local role authenticated;
select lives_ok($$insert into deliverables(id,project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('96000000-0000-4000-8000-000000000002','93000000-0000-4000-8000-000000000001','Manager output','Reviewed package','94000000-0000-4000-8000-000000000002','2026-08-15','91000000-0000-4000-8000-000000000002')$$,'Assigned manager creates with Project Member owner');
select is((select count(*) from deliverables),2::bigint,'Assigned manager reads');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000003',true);set local role authenticated;select is((select count(*) from deliverables),2::bigint,'Project Member reads');select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Denied','Criteria','94000000-0000-4000-8000-000000000002','2026-08-01','91000000-0000-4000-8000-000000000003')$$,'42501','new row violates row-level security policy for table "deliverables"','Project Member cannot create');select is_empty($$update deliverables set title='Owner edit' returning *$$,'Ownership grants no mutation');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000004',true);set local role authenticated;select is((select count(*) from deliverables),2::bigint,'Stakeholder reads');select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Denied','Criteria','94000000-0000-4000-8000-000000000002','2026-08-01','91000000-0000-4000-8000-000000000004')$$,'42501','new row violates row-level security policy for table "deliverables"','Stakeholder cannot create');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000005',true);set local role authenticated;select is((select count(*) from deliverables),2::bigint,'Read Only reads');select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Denied','Criteria','94000000-0000-4000-8000-000000000002','2026-08-01','91000000-0000-4000-8000-000000000005')$$,'42501','new row violates row-level security policy for table "deliverables"','Read Only cannot create');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000006',true);set local role authenticated;select is((select count(*) from deliverables),0::bigint,'Ordinary organization Member cannot read');select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Denied','Criteria','94000000-0000-4000-8000-000000000002','2026-08-01','91000000-0000-4000-8000-000000000006')$$,'42501','new row violates row-level security policy for table "deliverables"','Ordinary Member cannot create');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000007',true);set local role authenticated;select is((select count(*) from deliverables),0::bigint,'Inactive project member cannot read');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000008',true);set local role authenticated;select is((select count(*) from deliverables),0::bigint,'Inactive organization member cannot read');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000010',true);set local role authenticated;select is((select count(*) from deliverables where project_id='93000000-0000-4000-8000-000000000001'),0::bigint,'Cross-organization user cannot read');select is_empty($$update deliverables set title='Cross edit' where id='96000000-0000-4000-8000-000000000001' returning *$$,'Cross-organization manager cannot edit');reset role;
select set_config('request.jwt.claim.role','anon',true);select set_config('request.jwt.claim.sub','',true);set local role anon;select throws_ok($$select * from deliverables$$,'42501','permission denied for table deliverables','Anonymous cannot read');reset role;

select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$update deliverables set title='Admin edited' where id='96000000-0000-4000-8000-000000000001'$$,'Administrator edits non-terminal deliverable');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);set local role authenticated;select lives_ok($$update deliverables set title='Manager edited' where id='96000000-0000-4000-8000-000000000002'$$,'Assigned manager edits non-terminal deliverable');reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000009',true);set local role authenticated;select is_empty($$update deliverables set title='Sibling manager edit' where id='96000000-0000-4000-8000-000000000001' returning *$$,'Manager of another project cannot edit');reset role;

select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);set local role authenticated;
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad stakeholder','Criteria','94000000-0000-4000-8000-000000000003','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Stakeholder cannot own');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad read','Criteria','94000000-0000-4000-8000-000000000004','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Read Only cannot own');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad inactive','Criteria','94000000-0000-4000-8000-000000000005','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Inactive project membership cannot own');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad org','Criteria','94000000-0000-4000-8000-000000000006','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Inactive organization membership cannot own');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad project','Criteria','94000000-0000-4000-8000-000000000007','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Cross-project membership cannot own');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,created_by) values('93000000-0000-4000-8000-000000000001','Bad cross org','Criteria','94000000-0000-4000-8000-000000000008','2026-08-01','91000000-0000-4000-8000-000000000001')$$,'23514','The selected deliverable owner is not eligible.','Cross-organization membership cannot own');
select ok((select milestone_id='95000000-0000-4000-8000-000000000001' from deliverables where id='96000000-0000-4000-8000-000000000001'),'Same-project Planned milestone assigned');
select throws_ok($$update deliverables set milestone_id='95000000-0000-4000-8000-000000000002' where id='96000000-0000-4000-8000-000000000002'$$,'23514','The selected milestone does not belong to this project.','Cross-project milestone rejected');
select throws_ok($$update deliverables set milestone_id='95000000-0000-4000-8000-000000000003' where id='96000000-0000-4000-8000-000000000002'$$,'23514','The selected milestone does not belong to this project.','Cross-organization milestone rejected');
select throws_ok($$update deliverables set milestone_id='95000000-0000-4000-8000-000000000099' where id='96000000-0000-4000-8000-000000000002'$$,'23514','The selected milestone does not belong to this project.','Invalid milestone rejected');
select transition_milestone('95000000-0000-4000-8000-000000000001','Completed');select ok((select milestone_id is not null from deliverables where id='96000000-0000-4000-8000-000000000001'),'Historical milestone association survives terminal transition');

select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','start')$$,'Planned moves to In Progress');
select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','submit')$$,'In Progress submits');
select ok((select status='Ready for Acceptance' and submitted_at is not null from deliverables where id='96000000-0000-4000-8000-000000000001'),'Submission timestamp is trusted');
select throws_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','return')$$,'22023','Review feedback is required when returning a deliverable.','Return requires feedback');
select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','return','Provide signed evidence.')$$,'Ready deliverable returns with feedback');
select ok((select status='In Progress' and submitted_at is null and review_feedback='Provide signed evidence.' from deliverables where id='96000000-0000-4000-8000-000000000001'),'Return clears submission and preserves feedback');
select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','submit')$$,'Returned deliverable resubmits');
select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000001','accept')$$,'Ready deliverable accepted');
select ok((select status='Accepted' and accepted_at is not null and accepted_by='91000000-0000-4000-8000-000000000001' from deliverables where id='96000000-0000-4000-8000-000000000001'),'Acceptance stores trusted identity and timestamp');
select throws_ok($$update deliverables set status='In Progress' where id='96000000-0000-4000-8000-000000000001'$$,'42501','Terminal deliverables cannot be changed.','Accepted cannot reopen');
select throws_ok($$update deliverables set title='Edited terminal' where id='96000000-0000-4000-8000-000000000001'$$,'42501','Terminal deliverables cannot be changed.','Accepted cannot be edited');
select lives_ok($$select transition_deliverable('96000000-0000-4000-8000-000000000002','cancel')$$,'Non-terminal deliverable cancels');
select throws_ok($$update deliverables set status='Planned' where id='96000000-0000-4000-8000-000000000002'$$,'42501','Terminal deliverables cannot be changed.','Cancelled cannot reopen');
select throws_ok($$update deliverables set title='Edited cancelled' where id='96000000-0000-4000-8000-000000000002'$$,'42501','Terminal deliverables cannot be changed.','Cancelled cannot be edited');
select throws_ok($$insert into deliverables(project_id,title,acceptance_criteria,owner_membership_id,due_date,status,created_by) values('93000000-0000-4000-8000-000000000001','Invalid state','Criteria','94000000-0000-4000-8000-000000000002','2026-08-01','Accepted','91000000-0000-4000-8000-000000000001')$$,'23514','New deliverables must be Planned.','Invalid timestamp and initial status combination rejected');
select throws_ok($$update deliverables set project_id='93000000-0000-4000-8000-000000000002' where id='96000000-0000-4000-8000-000000000001'$$,'42501','Deliverable identity fields cannot be changed.','Deliverable cannot move projects');
select throws_ok($$update deliverables set created_by='91000000-0000-4000-8000-000000000002' where id='96000000-0000-4000-8000-000000000001'$$,'42501','Deliverable identity fields cannot be changed.','Creator identity immutable');
select throws_ok($$update deliverables set accepted_by='91000000-0000-4000-8000-000000000002' where id='96000000-0000-4000-8000-000000000001'$$,'42501','Accepting identity is trusted.','Accepting identity cannot be injected');
select throws_ok($$delete from deliverables where id='96000000-0000-4000-8000-000000000001'$$,'42501','permission denied for table deliverables','Direct delete denied');
reset role;
select * from finish();rollback;
